10716  static bool
 10717  check_block_stack(WASMLoaderContext *loader_ctx, BranchBlock *block,
 10718                    char *error_buf, uint32 error_buf_size)
 10719  {
 10720      BlockType *block_type = &block->block_type;
 10721      uint8 *return_types = NULL;
 10722      uint32 return_count = 0;
 10723      int32 available_stack_cell, return_cell_num, i;
 10724      uint8 *frame_ref = NULL;
 10725  #if WASM_ENABLE_GC != 0
 10726      WASMRefTypeMap *frame_reftype_map;
 10727      WASMRefTypeMap *return_reftype_maps = NULL, *return_reftype_map;
 10728      WASMRefType *ref_type;
 10729      uint32 param_count, return_reftype_map_count = 0;
 10730      int32 available_reftype_map =
 10731          (int32)(loader_ctx->reftype_map_num - block->reftype_map_num);
 10732  #endif
 10733
 10734      available_stack_cell =
 10735          (int32)(loader_ctx->stack_cell_num - block->stack_cell_num);
 10736
 10737  #if WASM_ENABLE_GC == 0
 10738      return_count = block_type_get_result_types(block_type, &return_types);
 10739  #else
 10740      return_count = block_type_get_result_types(block_type, &return_types,
 10741                                                 &return_reftype_maps,
 10742                                                 &return_reftype_map_count);
 10743      param_count =
 10744          block_type->is_value_type ? 0 : block_type->u.type->param_count;
 10745      (void)param_count;
 10746  #endif
 10747      return_cell_num =
 10748          return_count > 0 ? wasm_get_cell_num(return_types, return_count) : 0;
 10749
 10750      /* If the stack is in polymorphic state, just clear the stack
 10751       * and then re-push the values to make the stack top values
 10752       * match block type. */
 10753      if (block->is_stack_polymorphic) {
 10754  #if WASM_ENABLE_GC != 0
 10755          int32 j = return_reftype_map_count - 1;
 10756  #endif
 10757          for (i = (int32)return_count - 1; i >= 0; i--) {
 10758  #if WASM_ENABLE_GC != 0
 10759              if (wasm_is_type_multi_byte_type(return_types[i])) {
 10760                  bh_assert(return_reftype_maps[j].index == i + param_count);
 10761                  bh_memcpy_s(
 10762                      loader_ctx->ref_type_tmp, sizeof(WASMRefType),
 10763                      return_reftype_maps[j].ref_type,
 10764                      wasm_reftype_struct_size(return_reftype_maps[j].ref_type));
 10765                  j--;
 10766              }
 10767  #endif
 10768  #if WASM_ENABLE_FAST_INTERP != 0
 10769              POP_OFFSET_TYPE(return_types[i]);
 10770  #endif
 10771              POP_TYPE(return_types[i]);
 10772          }
 10773
 10774          /* Check stack is empty */
 10775          if (loader_ctx->stack_cell_num != block->stack_cell_num) {
 10776              set_error_buf(
 10777                  error_buf, error_buf_size,
 10778                  "type mismatch: stack size does not match block type");
 10779              goto fail;
 10780          }
 10781
 10782  #if WASM_ENABLE_GC != 0
 10783          j = 0;
 10784  #endif
 10785          for (i = 0; i < (int32)return_count; i++) {
 10786  #if WASM_ENABLE_GC != 0
 10787              if (wasm_is_type_multi_byte_type(return_types[i])) {
 10788                  bh_assert(return_reftype_maps[j].index == i + param_count);
 10789                  bh_memcpy_s(
 10790                      loader_ctx->ref_type_tmp, sizeof(WASMRefType),
 10791                      return_reftype_maps[j].ref_type,
 10792                      wasm_reftype_struct_size(return_reftype_maps[j].ref_type));
 10793                  j++;
 10794              }
 10795  #endif
 10796  #if WASM_ENABLE_FAST_INTERP != 0
 10797              bool disable_emit = true;
 10798              int16 operand_offset = 0;
 10799              PUSH_OFFSET_TYPE(return_types[i]);
 10800  #endif
 10801              PUSH_TYPE(return_types[i]);
 10802          }
 10803          return true;
 10804      }
 10805
 10806      if (available_stack_cell != return_cell_num) {
 10807  #if WASM_ENABLE_EXCE_HANDLING != 0
 10808          /* testspec: this error message format is expected by try_catch.wast */
 10809          snprintf(
 10810              error_buf, error_buf_size, "type mismatch: %s requires [%s]%s[%s]",
 10811              block->label_type == LABEL_TYPE_TRY
 10812                      || (block->label_type == LABEL_TYPE_CATCH
 10813                          && return_cell_num > 0)
 10814                  ? "instruction"
 10815                  : "block",
 10816              return_cell_num > 0 ? type2str(return_types[0]) : "",
 10817              " but stack has ",
 10818              available_stack_cell > 0 ? type2str(*(loader_ctx->frame_ref - 1))
 10819                                       : "");
 10820          goto fail;
 10821  #else
 10822          set_error_buf(error_buf, error_buf_size,
 10823                        "type mismatch: stack size does not match block type");
 10824          goto fail;
 10825  #endif
 10826      }
 10827
 10828      /* Check stack values match return types */
 10829      frame_ref = loader_ctx->frame_ref;
 10830  #if WASM_ENABLE_GC != 0
 10831      frame_reftype_map = loader_ctx->frame_reftype_map;
 10832      return_reftype_map =
 10833          return_reftype_map_count
 10834              ? return_reftype_maps + return_reftype_map_count - 1
 10835              : NULL;
 10836  #endif
 10837      for (i = (int32)return_count - 1; i >= 0; i--) {
 10838          uint8 type = return_types[i];
 10839  #if WASM_ENABLE_GC != 0
 10840          bool is_type_multi_byte = wasm_is_type_multi_byte_type(type);
 10841          ref_type = NULL;
 10842          if (is_type_multi_byte) {
 10843              bh_assert(return_reftype_map);
 10844              ref_type = return_reftype_map->ref_type;
 10845          }
 10846  #endif
 10847          if (!check_stack_top_values(loader_ctx, frame_ref, available_stack_cell,
 10848  #if WASM_ENABLE_GC != 0
 10849                                      frame_reftype_map, available_reftype_map,
 10850  #endif
 10851                                      type,
 10852  #if WASM_ENABLE_GC != 0
 10853                                      ref_type,
 10854  #endif
 10855                                      error_buf, error_buf_size))
 10856              return false;
 10857          frame_ref -= wasm_value_type_cell_num(return_types[i]);
 10858          available_stack_cell -= wasm_value_type_cell_num(return_types[i]);
 10859  #if WASM_ENABLE_GC != 0
 10860          if (is_type_multi_byte) {
 10861              frame_reftype_map--;
 10862              available_reftype_map--;
 10863              return_reftype_map--;
 10864          }
 10865  #endif
 10866      }
 10867
 10868      return true;
 10869
 10870  fail:
 10871      return false;
 10872  }
